import csv, datetime, statistics, math
rows=list(csv.DictReader(open('data.csv')))
d={}
for r in rows:
    dt=datetime.date.fromisoformat(r['date'])
    d.setdefault(r['band'],[]).append((dt,float(r['y'])))
for b,v in d.items():
    v.sort()
    # climatology: mean by day-of-year with window +-10 days
    def clim(target):
        vals=[y for dt,y in v if abs((dt-target).days)<=10]
        return statistics.mean(vals)
    errs=[]
    for dt,y in v:
        # leave-one-out-ish: fine, just check
        errs.append(y-clim(dt))
    rmse=math.sqrt(statistics.mean(e*e for e in errs))
    print(b,'clim rmse',round(rmse,3))
    # residual trend by year
    res={}
    for (dt,y),e in zip(v,errs): res.setdefault(dt.year,[]).append(e)
    print('  resid yearly mean',{y:round(statistics.mean(x),3) for y,x in sorted(res.items())})
