import csv, statistics, json, datetime
from collections import defaultdict
d=defaultdict(dict); dates={}
for r in csv.DictReader(open("data.csv")):
    d[r["band"]][r["period_id"]]=float(r["y"]); dates[r["period_id"]]=r["date"]
periods=sorted(dates,key=lambda p:dates[p])
vp={row["period_id"]:row["date"] for row in csv.DictReader(open("visits_to_predict.csv"))}
order=sorted(vp,key=lambda p:vp[p])
out={}
for b in d:
    bym=defaultdict(list)
    for p in periods: bym[dates[p][5:7]].append(d[b][p])
    clim={m:statistics.mean(v) for m,v in bym.items()}
    xs=[d[b][p]-clim[dates[p][5:7]] for p in periods]
    mean=statistics.mean(xs)
    num=sum((xs[i]-mean)*(xs[i+1]-mean) for i in range(len(xs)-1))
    den=sum((x-mean)**2 for x in xs)
    phi=max(num/den,0.0)  # clamp negative autocorrelation to 0
    lastp=periods[-1]
    r=d[b][lastp]-clim[dates[lastp][5:7]]
    lastdate=datetime.date.fromisoformat(dates[lastp])
    res={}
    for p in order:
        steps=(datetime.date.fromisoformat(vp[p])-lastdate).days/5.0
        res[p]=clim[vp[p][5:7]]+mean+(r-mean)*phi**steps
    out[b]=res
answer={"prediction":{p:{b:round(out[b][p],4) for b in out} for p in order},
 "rationale":"The parcel's own 220 observed visits (2020-09 to 2024-09) show stable monthly seasonality with no material trend for VH, VV and VV-VH. I forecast each visit as the climatological mean for its calendar month (estimated from the parcel's own history) plus the current anomaly decayed by the estimated lag-1 autocorrelation of the residuals (clamped at 0 since it was slightly negative, i.e. no persistent anomaly). This is a synthetic-control-style use of the parcel's own history: the seasonal cycle is the recurring structure, and the anomaly term vanishes within a few visits."}
json.dump(answer,open("answer.json","w"),indent=1)
print(json.dumps(answer["prediction"]["P221"]), json.dumps(answer["prediction"]["P271"]))
