import csv, json, collections, datetime as dt, statistics as st
rows=list(csv.DictReader(open('data.csv')))
d=collections.defaultdict(list)  # band -> list of (date, y)
for r in rows:
    d[r['band']].append((dt.date.fromisoformat(r['date']), float(r['y'])))
targets=[(r['period_id'], dt.date.fromisoformat(r['date'])) for r in csv.DictReader(open('visits_to_predict.csv'))]
pred={}
for pid,td in targets:
    pred[pid]={}
    for b,series in d.items():
        # seasonal analog: same calendar window (+/- 12 days) in past years
        cands=[y for (dd,y) in series if abs((dd.replace(year=td.year)-td).days)<=12 and dd<td]
        if not cands:
            cands=[y for (dd,y) in series if dd<td][-4:]
        pred[pid][b]=round(st.mean(cands),4)
json.dump({"prediction":pred,"rationale":"Seasonal-analog (SHC-style) forecast: each target visit's band values are the mean of that parcel's own historical visits within +/-12 days of the same calendar window in earlier years (2020-2024). The series show a stable annual cycle (VH ~-15.0 dB, VV ~-9.0 dB, VV-VH ~6.0 dB) with no trend, so matching the treated date to its own historical seasonal analogs and averaging them gives the counterfactual band means."}, open('answer.json','w'), indent=1)
print(json.dumps(pred['P221']), json.dumps(pred['P271']))
