for r in rows:
    series.setdefault(r["band"],[]).append(float(r["y"]))
def backtest(fn, h=27):
    errs={b:[] for b in series}
    for b,ys in series.items():
        n=len(ys)
        for t in range(n-h,n):
            pred=fn(ys[:t])
            errs[b].append(abs(pred-ys[t]))
    return {b:round(statistics.mean(e),4) for b,e in errs.items()}
def persist(ys): return ys[-1]
def mean3(ys): return statistics.mean(ys[-3:])
def mean6(ys): return statistics.mean(ys[-6:])
def seas(ys,lag=30,k=3):
    return statistics.mean(ys[-lag*i] for i in range(1,k+1))
def seasblend(ys,lag=30,k=3):
    s=statistics.mean(ys[-lag*i] for i in range(1,k+1))
    r=statistics.mean(ys[-3:])
    return 0.5*s+0.5*r
for name,fn in [("persist",persist),("mean3",mean3),("mean6",mean6),
