import csv, datetime, collections, statistics, math
rows=list(csv.DictReader(open("data.csv")))
d=collections.defaultdict(list)
for r in rows:
    d[r["band"]].append((datetime.date.fromisoformat(r["date"]), float(r["y"])))
for b in d: d[b].sort()

def doy(ser, target, hw=15, yw=1.0):
    num=den=0
    for dt,y in ser:
        dd=abs((dt-dt.replace(year=target.year)).days); dd=min(dd,365-dd)
        if dd<=hw:
            w=math.exp(-(dd/hw)**2*2)*yw**(target.year-dt.year)
            num+=w*y; den+=w
    return num/den

H=44
for yw in [1.0,0.7,0.5,0.3]:
    errs=[]
    for b,ser in d.items():
        train=ser[:-H]
        for dt,y in ser[-H:]:
            errs.append(abs(doy(train,dt,15,yw)-y))
    print("yw",yw,"MAE",round(statistics.mean(errs),4))

# seasonal + recent anomaly correction
def doy_anom(ser,target,hw=15,yw=1.0,na=5):
    base=doy(ser,target,hw,yw)
    # expected value at recent obs vs actual
    num=den=0
    for dt,y in ser[-na:]:
        e=doy(ser[:-na],dt,hw,yw)
        if e is not None:
            num+=y-e; den+=1
    return base+(num/den if den else 0)
for na in [3,5,8]:
    errs=[]
    for b,ser in d.items():
        train=ser[:-H]
        for dt,y in ser[-H:]:
            errs.append(abs(doy_anom(train,dt,15,1.0,na)-y))
    print("anom na",na,"MAE",round(statistics.mean(errs),4))
