import csv, collections, math, datetime
rows=list(csv.DictReader(open("data.csv")))
by=collections.defaultdict(dict); dates={}
for r in rows: by[r["period_id"]][r["band"]]=float(r["y"]); dates[r["period_id"]]=r["date"]
periods=sorted(by, key=lambda p:int(p[1:]))
t0=datetime.date.fromisoformat(dates[periods[0]])
X=[(datetime.date.fromisoformat(dates[p])-t0).days for p in periods]
def design(X,K,tr):
    cols=[[1.0]*len(X)]
    if tr: cols.append([x/365.25 for x in X])
    for k in range(1,K+1):
        cols.append([math.sin(2*math.pi*k*x/365.25) for x in X])
        cols.append([math.cos(2*math.pi*k*x/365.25) for x in X])
    return list(zip(*cols))
def fit(y,X,K,tr):
    D=design(X,K,tr); n=len(y); p=len(D[0])
    A=[[sum(D[r][i]*D[r][j] for r in range(n)) for j in range(p)] for i in range(p)]
    v=[sum(D[r][i]*y[r] for r in range(n)) for i in range(p)]
    for i in range(p):
        piv=max(range(i,p),key=lambda r:abs(A[r][i])); A[i],A[piv]=A[piv],A[i]; v[i],v[piv]=v[piv],v[i]
        for r in range(i+1,p):
            f=A[r][i]/A[i][i]
            for c in range(i,p): A[r][c]-=f*A[i][c]
            v[r]-=f*v[i]
    coef=[0]*p
    for i in reversed(range(p)):
        coef[i]=(v[i]-sum(A[i][j]*coef[j] for j in range(i+1)))/A[i][i]
    resid=[y[i]-sum(coef[j]*D[i][j] for j in range(p)) for i in range(n)]
    return coef, math.sqrt(sum(r*r for r in resid)/n)
for b in ['B8','NDVI','NDWI','B4']:
    y=[by[p][b] for p in periods]
    for K in [1,2,3]:
        for tr in [False,True]:
            c,rmse=fit(y,X,K,tr)
            print(b,K,tr,round(rmse,4))
