    mx=sum(p[0]*p[2] for p in pts)/sw
    my=sum(p[1]*p[2] for p in pts)/sw
    sxx=sum(p[2]*(p[0]-mx)**2 for p in pts)
    sxy=sum(p[2]*(p[0]-mx)*(p[1]-my) for p in pts)
