for r in rows:
    data.setdefault(r["band"],[]).append((date.fromisoformat(r["date"]), float(r["y"])))
for b in data: data[b].sort()

def doy(d): return d.timetuple().tm_yday
def angdist(a,b):
    d=abs(a-b)%365
    return min(d,365-d)

def predict(series, target, width, trim=True):
    td=doy(target)
    vals=[]
    for d,y in series:
        if d>=target: continue
        w=math.exp(-(angdist(doy(d),td)/width)**2)
        vals.append((w,y))
    if not vals: return None
    if trim:
        ys=[y for _,y in vals]
        med=statistics.median(ys)
        mad=statistics.median([abs(y-med) for y in ys]) or 1e-9
        vals=[(w,y) for w,y in vals if abs(y-med)<3.5*1.4826*mad]
    sw=sum(w for w,_ in vals)
    return sum(w*y for w,y in vals)/sw

# backtest: predict each observed point from strictly earlier data, per width
for width in [5,8,12,18,25]:
    errs={b:[] for b in data}
    for b,series in data.items():
        for i,(d,y) in enumerate(series):
