    pts=[(doy(d), d.year, y) for d,y in ser]
    if year_adj:
        # regress y on doy-smooth residual per year
        # iterate: smooth then year effects
        for _ in range(3):
            sm={}
            for i,(dd,yr,y) in enumerate(pts):
                num=den=0.0
                for dd2,yr2,y2 in pts:
                    if (dd2,yr2)==(dd,yr): continue
                    w=math.exp(-0.5*(circdist(dd,dd2)/h)**2)
                    num+=w*y2; den+=w
                sm[i]=num/den if den else y
            ym=defaultdict(list)
            for i,(dd,yr,y) in enumerate(pts): ym[yr].append(y-sm[i])
            yr_eff={yr:statistics.mean(v) for yr,v in ym.items()}
            yrs=sorted(yr_eff)
            # linear fit of year effects
            xs=[yr-yrs[0] for yr in yrs]; ys=[yr_eff[yr] for yr in yrs]
            mx=statistics.mean(xs);my=statistics.mean(ys)
            slope=sum((x-mx)*(y-my) for x,y in zip(xs,ys))/sum((x-mx)**2 for x in xs)
            def trend(yr): return my+slope*(yr-yrs[0]-mx)
            pts=[(dd,yr,y-trend(yr)+my) for dd,yr,y in pts]
        return pts, trend
    return pts, None

def loocv(ser,h,year_adj):
    pts,trend=fit(ser,h,year_adj)
    errs=[]
    for i,(dd,yr,y) in enumerate(pts):
        num=den=0.0
        for dd2,yr2,y2 in pts:
            if (dd2,yr2)==(dd,yr): continue
            w=math.exp(-0.5*(circdist(dd,dd2)/h)**2)
            num+=w*y2; den+=w
        pred=num/den if den else statistics.mean([p[2] for p in pts])
        if trend: pred+=trend(yr)-statistics.mean([trend(p[1]) for p in pts])
        errs.append(abs(pred-y))
