    d=datetime.date.fromisoformat(r["date"])
    data[r["band"]].append((d,float(r["y"])))
for b in data: data[b].sort()

def design(d,K=3):
    t=d.timetuple().tm_yday/366*2*math.pi
    x=[1.0]
    for k in range(1,K+1): x+=[math.cos(k*t),math.sin(k*t)]
    return x
def lstsq(A,y):
    n=len(A[0])
    ATA=[[sum(a[i]*a[j] for a in A) for j in range(n)] for i in range(n)]
    ATy=[sum(a[i]*yi for a,yi in zip(A,y)) for i in range(n)]
    M=[row[:]+[ATy[i]] for i,row in enumerate(ATA)]
    for c in range(n):
        p=max(range(c,n),key=lambda r:abs(M[r][c])); M[c],M[p]=M[p],M[c]
        for r in range(n):
            if r!=c:
                f=M[r][c]/M[c][c]
                for k in range(c,n+1): M[r][k]-=f*M[c][k]
    return [M[i][n]/M[i][i] for i in range(n)]

